99	export async function CreateMLCEngine(
100	  modelId: string | string[],
101	  engineConfig?: MLCEngineConfig,
102	  chatOpts?: ChatOptions | ChatOptions[],
103	): Promise<MLCEngine> {
104	  const engine = new MLCEngine(engineConfig);
