async handleTask<T extends MessageContent>(
  uuid: string,
  task: () => Promise<T>,
) {
  try {
    const res = await task();
    const msg: WorkerResponse = {
      kind: "return",
      uuid: uuid,
      content: res,
    };
    this.postMessage(msg);
  } catch (err) {
    const errStr = (err as object).toString();
    const msg: WorkerResponse = {
      kind: "throw",
      uuid: uuid,
      content: errStr,
    };
    this.postMessage(msg);
  }
}

